SELECT "Generico_5"."Anunciante" AS "Datos__copia_",   CAST(EXTRACT(MONTH FROM "Generico_5"."FECHA") AS BIGINT) AS "mn_FECHA_ok",   SUM("Generico_5"."InversionUS") AS "sum_Calculation_0061002123102817_ok",   CAST(EXTRACT(YEAR FROM "Generico_5"."FECHA") AS BIGINT) AS "yr_FECHA_ok" FROM "Generico_5" WHERE (("Generico_5"."Anunciante" IN ('BANTRAB/TODOTICKET', 'TODOTICKET', 'TODOTICKET.COM')) AND (CAST(EXTRACT(YEAR FROM "Generico_5"."FECHA") AS BIGINT) IN (2014, 2015))) GROUP BY "Generico_5"."Anunciante", "mn_FECHA_ok", "yr_FECHA_ok";
